using Avalonia.Controls; using Avalonia.Interactivity;
namespace TCMPlus.App.Views;
public partial class MessageWindow : Window { private readonly bool _confirmation; public MessageWindow(string heading,string message,bool confirmation=false) { InitializeComponent(); _confirmation=confirmation; Heading.Text=heading; Message.Text=message; CancelButton.IsVisible=confirmation; ConfirmButton.Content=confirmation?"Delete":"OK"; } public MessageWindow():this("",""){} private void OnCancel(object? s,RoutedEventArgs e)=>Close(false); private void OnConfirm(object? s,RoutedEventArgs e)=>Close(_confirmation); }
